//! RFC 5424 §6: a syslog message is a PRI in angle brackets, a version digit, then
//! space-separated timestamp, hostname, app-name, procid and msgid, then
//! structured data and the message. RFC 3164 §4.1 is the older form: the same PRI,
//! then a timestamp and hostname in a fixed textual shape. Facility and severity
//! are PRI divided by and modulo 8 (RFC 5424 §6.2.1). It is text, not a field
//! table (DEVIATIONS T1).
//!
//! Generated by dev/protogen from dev/protogen/specs/syslog.toml. Field layouts
//! come from the RFC cited above; edit the spec, not this file.

use crate::field::FieldDesc;
use crate::proto::{ProtoDesc, ProtoId};

// protogen:hand begin
use crate::layers::text;
use crate::options::Item;

/// RFC 5424 §6.2.1: "<" then up to three digits then ">".
fn pri_of(hdr: &[u8]) -> Option<(u64, usize)> {
    if hdr.first() != Some(&b'<') {
        return None;
    }
    let end = hdr.iter().take(6).position(|c| *c == b'>')?;
    let digits = hdr.get(1..end)?;
    if digits.is_empty() || !digits.iter().all(|c| c.is_ascii_digit()) {
        return None;
    }
    Some((
        digits.iter().fold(0u64, |a, c| a * 10 + (*c - b'0') as u64),
        end + 1,
    ))
}

fn parse_options(hdr: &[u8]) -> Vec<Item> {
    let mut out = Vec::new();
    let rest = match pri_of(hdr) {
        Some((pri, at)) => {
            out.push(Item::uint("pri", 0, pri));
            // RFC 5424 §6.2.1.
            out.push(Item::uint("facility", 1, pri / 8));
            out.push(Item::uint("severity", 2, pri % 8));
            hdr.get(at..).unwrap_or(&[])
        }
        None => hdr,
    };
    let line = text::lines(rest).into_iter().next().unwrap_or(rest);
    let parts: Vec<&[u8]> = line.splitn(8, |c| *c == b' ').collect();
    // RFC 5424 §6.2.2 puts a version digit first; RFC 3164 §4.1.2 puts a month
    // name there instead, and has no structured header to split.
    if line.first().is_some_and(|c| c.is_ascii_digit()) && parts.len() >= 7 {
        for (n, v) in [
            "version",
            "timestamp",
            "hostname",
            "app-name",
            "procid",
            "msgid",
            "structured-data",
            "msg",
        ]
        .iter()
        .zip(parts.iter())
        {
            out.push(text::named(n, v));
        }
    } else {
        out.push(text::named("msg", line));
    }
    out
}
// protogen:hand end

pub static FIELDS: &[FieldDesc] = &[FieldDesc::var_bytes_to_end("headers", 0)];

pub static DESC: ProtoDesc = ProtoDesc {
    id: ProtoId::Syslog,
    name: "Syslog",
    fields: FIELDS,
    min_len: 3,
    header_len: crate::proto::header_len_rest,
    next: crate::proto::next_end,
    build_len: 3,
    parse_options: Some(parse_options),
    opt_table: None,
    set_hlen: None,
    bind_next: None,
    bind_next_bytes: None,
    content_len: None,
};

#[cfg(test)]
mod tests {
    #![allow(unused_imports)]
    use super::*;
    use crate::field::FieldValue;
    use crate::packet::Packet;

    // protogen:tests begin
    /// RFC 5424 §6.5 Example 1: PRI 34 (facility 4, severity 2), version 1.
    fn vector() -> Vec<u8> {
        vec![
            0x3c, 0x33, 0x34, 0x3e, 0x31, 0x20, 0x32, 0x30, 0x30, 0x33, 0x2d, 0x31, 0x30, 0x2d,
            0x31, 0x31, 0x54, 0x32, 0x32, 0x3a, 0x31, 0x34, 0x3a, 0x31, 0x35, 0x2e, 0x30, 0x30,
            0x33, 0x5a, 0x20, 0x68, 0x6f, 0x73, 0x74, 0x20, 0x73, 0x75, 0x20, 0x2d, 0x20, 0x49,
            0x44, 0x34, 0x37, 0x20, 0x2d, 0x20, 0x6d, 0x73, 0x67,
        ]
    }

    #[test]
    fn dissects_the_rfc_vector() {
        let p = Packet::dissect(vector(), ProtoId::Syslog);
        assert!(p.find_layer(ProtoId::Syslog).is_some());

        assert_eq!(p.raw_bytes(), &vector()[..]);
    }

    #[test]
    fn truncation_does_not_panic() {
        for n in 0..vector().len() {
            let p = Packet::dissect(vector()[..n].to_vec(), ProtoId::Syslog);
            assert_eq!(p.raw_bytes(), &vector()[..n]);
        }
    }

    #[test]
    fn writes_survive_a_rebuild() {
        let mut p = Packet::dissect(vector(), ProtoId::Syslog);
        let l = p.find_layer(ProtoId::Syslog).unwrap();
        let n = p.raw_bytes().len();
        for f in crate::proto::active_fields(ProtoId::Syslog, false, p.header(l))
            .filter(|f| f.kind == crate::field::FieldKind::Uint && f.bit_len <= 32)
            .map(|f| f.name)
            .collect::<Vec<_>>()
        {
            p.set_uint(l, f, 1);
        }
        assert_eq!(p.to_bytes().len(), n);
    }
    // protogen:tests end
}
